"""Generated by the QA agent for STORY-107: Sign out and end my session."""
import re

from playwright.sync_api import expect


def test_tc_107_01_sign_out_shows_message_ui(signed_in):
    """TC-107-01 (UI)"""
    signed_in.get_by_test_id("logout-link").click()
    expect(signed_in.get_by_test_id("signed-out-message")).to_be_visible()


def test_tc_107_02_accounts_page_needs_sign_in_again_ui(signed_in):
    """TC-107-02 (UI)"""
    signed_in.get_by_test_id("logout-link").click()
    signed_in.goto("/dashboard")
    expect(signed_in).to_have_url(re.compile(r".*/login(\?.*)?$"))


def test_tc_107_03_token_rejected_after_logout_api(amira):
    """TC-107-03 (API, security)"""
    assert amira.get("/api/me").status_code == 200
    assert amira.post("/api/auth/logout").status_code == 200
    r = amira.get("/api/accounts")
    assert r.status_code == 401, f"session token still works after logout: {r.status_code} {r.text[:120]}"
